      --color-bg: #090b10;
      --color-surface: #141823;
      --color-surface-strong: #1b2030;
      --color-surface-soft: #23293b;
      --color-text: #f5f7fb;
      --color-muted-text: #afb8cc;
      --color-border: #38415a;
      --color-focus: #8ab4ff;
      --color-danger: #ff6b81;
      --color-danger-strong: #ff3f64;
      --color-danger-text: #1d0b0f;
      --shadow-lg: 0 24px 70px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      margin: 0;
      min-height: 100%;
      background:
        radial-gradient(circle at top, #1c2340 0, #0a0d15 45%, #090b10 100%);
      color: var(--color-text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    body {
      min-height: 100vh;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--color-text);
      color: #05070d;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 20;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page-shell {
      width: min(100%, 76rem);
      margin: 0 auto;
      padding: 2rem 1.25rem 3rem;
    }

    .page-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 2rem;
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--color-muted-text);
      font-size: 0.875rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1.05;
    }

    .header-copy {
      max-width: 42rem;
    }

    .header-copy p {
      margin: 0.75rem 0 0;
      color: var(--color-muted-text);
      font-size: 1rem;
      line-height: 1.6;
    }

    .page-badge {
      padding: 0.7rem 1rem;
      border: 1px solid var(--color-border);
      border-radius: 999px;
      background: rgba(20, 24, 35, 0.8);
      color: var(--color-muted-text);
      font-size: 0.95rem;
      white-space: nowrap;
    }

    .preview-layout {
      display: grid;
      grid-template-columns: minmax(0, 1.6fr) minmax(16rem, 1fr);
      gap: 1.5rem;
    }

    .card {
      border: 1px solid var(--color-border);
      border-radius: 1.5rem;
      background: linear-gradient(180deg, rgba(27, 32, 48, 0.95), rgba(20, 24, 35, 0.98));
      box-shadow: var(--shadow-lg);
    }

    .preview-card {
      overflow: hidden;
    }

    .image-frame {
      position: relative;
      aspect-ratio: 4 / 3;
      background:
        linear-gradient(135deg, rgba(75, 96, 173, 0.35), rgba(13, 16, 25, 0.1)),
        linear-gradient(180deg, #1c2030, #111520);
    }

    .image-frame img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .image-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      justify-content: space-between;
      padding: 1.25rem 1.25rem 0;
      color: var(--color-muted-text);
    }

    .image-title {
      padding: 0 1.25rem;
    }

    .image-title h2 {
      margin: 1rem 0 0.35rem;
      font-size: 1.5rem;
    }

    .image-title p {
      margin: 0;
      color: var(--color-muted-text);
      line-height: 1.6;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.875rem;
      padding: 1.5rem 1.25rem 1.25rem;
    }

    button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.9rem 1.2rem;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
      transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible,
    .skip-link:focus-visible {
      outline: 3px solid var(--color-focus);
      outline-offset: 3px;
    }

    .secondary-button {
      border-color: var(--color-border);
      background: var(--color-surface-soft);
      color: var(--color-text);
    }

    .trigger,
    .danger-button {
      border-color: #9e3045;
      background: linear-gradient(180deg, var(--color-danger), var(--color-danger-strong));
      color: var(--color-danger-text);
    }

    .trigger[disabled],
    .secondary-button[disabled],
    .danger-button[disabled] {
      opacity: 1;
      cursor: not-allowed;
      transform: none;
      background: #3d4150;
      border-color: #52586a;
      color: #d9deea;
    }

    .details-card {
      padding: 1.25rem;
    }

    .details-card h2 {
      margin: 0 0 1rem;
      font-size: 1.2rem;
    }

    .details-list {
      display: grid;
      gap: 0.9rem;
      margin: 0;
    }

    .details-list div {
      padding-bottom: 0.9rem;
      border-bottom: 1px solid var(--color-border);
    }

    .details-list div:last-child {
      padding-bottom: 0;
      border-bottom: 0;
    }

    .details-list dt {
      margin: 0 0 0.35rem;
      color: var(--color-muted-text);
      font-size: 0.88rem;
    }

    .details-list dd {
      margin: 0;
      font-size: 1rem;
    }

    .status {
      min-height: 1.5rem;
      margin-top: 1rem;
      color: #c8f0d1;
      font-weight: 600;
    }

    dialog {
      width: min(calc(100vw - 2rem), 30rem);
      padding: 0;
      border: 1px solid var(--color-border);
      border-radius: 1.4rem;
      background: linear-gradient(180deg, #171b29, #111521);
      color: var(--color-text);
      box-shadow: var(--shadow-lg);
    }

    dialog::backdrop {
      background: rgba(2, 4, 10, 0.76);
      backdrop-filter: blur(6px);
    }

    .dialog-panel {
      padding: 1.5rem;
    }

    .dialog-panel h2 {
      margin: 0 0 0.75rem;
      font-size: 1.55rem;
    }

    .dialog-panel p {
      margin: 0;
      color: var(--color-muted-text);
      line-height: 1.65;
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 0.8rem;
      margin-top: 1.5rem;
    }

    @media (max-width: 48rem) {
      .page-header,
      .preview-layout {
        grid-template-columns: 1fr;
        display: grid;
      }

      .page-badge {
        justify-self: start;
      }
    }

    @media (forced-colors: active) {
      :root {
        --color-bg: Canvas;
        --color-surface: Canvas;
        --color-surface-strong: Canvas;
        --color-surface-soft: Canvas;
        --color-text: CanvasText;
        --color-muted-text: CanvasText;
        --color-border: ButtonBorder;
        --color-focus: Highlight;
        --color-danger: ButtonFace;
        --color-danger-strong: ButtonFace;
        --color-danger-text: ButtonText;
      }

      body,
      .card,
      dialog,
      .page-badge,
      .secondary-button,
      .trigger,
      .danger-button {
        background: Canvas;
        color: CanvasText;
        box-shadow: none;
      }

      .secondary-button,
      .trigger,
      .danger-button,
      .card,
      dialog,
      .page-badge {
        border: 1px solid ButtonBorder;
      }

      button:focus-visible,
      .skip-link:focus-visible {
        outline: 2px solid Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const image = {
      title: "Golden Hour Reflection",
      alt: "A person standing by a lake at sunset, looking across the water toward mountain silhouettes.",
      photographer: "Maya Chen",
      location: "Lake Crescent, Washington",
      size: "5472 x 3648",
      collection: "Landscape Studies",
      added: "Added to library today",
      src: "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80"
    };

    const Header = () => `
      <header class="page-header">
        <div class="header-copy">
          <p class="eyebrow">Image library</p>
          <h1>Preview image</h1>
          <p>Review the selected image, confirm details, and remove it from your library only if you are sure.</p>
        </div>
        <div class="page-badge" aria-label="Current section">Dark gallery view</div>
      </header>
    `;

    const PreviewCard = () => `
      <article class="card preview-card" aria-labelledby="image-title">
        <div class="image-frame">
          <img src="${image.src}" alt="${image.alt}">
        </div>
        <div class="image-meta">
          <span>${image.added}</span>
          <span>Curated in ${image.collection}</span>
        </div>
        <div class="image-title">
          <h2 id="image-title">${image.title}</h2>
          <p>Captured by ${image.photographer}. This image is currently stored in your personal library.</p>
        </div>
        <div class="actions">
          <button type="button" class="secondary-button">Download</button>
          <button type="button" class="trigger" id="delete-trigger">Delete image</button>
        </div>
      </article>
    `;

    const DetailsCard = () => `
      <aside class="card details-card" aria-labelledby="details-heading">
        <h2 id="details-heading">Image details</h2>
        <dl class="details-list">
          <div>
            <dt>Photographer</dt>
            <dd>${image.photographer}</dd>
          </div>
          <div>
            <dt>Location</dt>
            <dd>${image.location}</dd>
          </div>
          <div>
            <dt>Resolution</dt>
            <dd>${image.size}</dd>
          </div>
          <div>
            <dt>Collection</dt>
            <dd>${image.collection}</dd>
          </div>
        </dl>
        <p class="status" id="status-message" aria-live="polite"></p>
      </aside>
    `;

    const DeleteDialog = () => `
      <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
        <form method="dialog" class="dialog-panel">
          <h2 id="delete-dialog-title">Delete this image from your library?</h2>
          <p id="delete-dialog-description">This will remove <strong>${image.title}</strong> from your library. You can cancel to keep the image available.</p>
          <div class="dialog-actions">
            <button type="submit" class="secondary-button" value="cancel" autofocus>Cancel</button>
            <button type="submit" class="danger-button" value="delete">Delete image</button>
          </div>
        </form>
      </dialog>
    `;

    const App = () => `
      <div class="page-shell">
        ${Header()}
        <main id="main-content" tabindex="-1">
          <section class="preview-layout" aria-label="Image preview content">
            ${PreviewCard()}
            ${DetailsCard()}
          </section>
        </main>
      </div>
      ${DeleteDialog()}
    `;

    const root = document.getElementById("app");
    root.innerHTML = App();

    const dialog = document.getElementById("delete-dialog");
    const trigger = document.getElementById("delete-trigger");
    const statusMessage = document.getElementById("status-message");

    trigger.addEventListener("click", () => {
      dialog.showModal();
    });

    dialog.addEventListener("close", () => {
      if (dialog.returnValue === "delete") {
        statusMessage.textContent = `"${image.title}" was deleted from your library.`;
        trigger.disabled = true;
        trigger.textContent = "Image deleted";
      }
    });
  </script>
</body>
</html>
