    .preview-card {
      overflow: hidden;
    }

    .image-frame {
      position: relative;
      aspect-ratio: 4 / 3;
      background:
        linear-gradient(135deg, rgba(75, 96, 173, 0.35), rgba(13, 16, 25, 0.1)),
        linear-gradient(180deg, #1c2030, #111520);
    }

    .image-frame img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .image-meta {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      justify-content: space-between;
      padding: 1.25rem 1.25rem 0;
      color: var(--color-muted-text);
    }

    .image-title {
      padding: 0 1.25rem;
    }

    .image-title h2 {
      margin: 1rem 0 0.35rem;
      font-size: 1.5rem;
    }

    .image-title p {
      margin: 0;
      color: var(--color-muted-text);
      line-height: 1.6;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.875rem;
