      color: var(--color-text);
    }

    .trigger,
    .danger-button {
      border-color: #9e3045;
      background: linear-gradient(180deg, var(--color-danger), var(--color-danger-strong));
      color: var(--color-danger-text);
    }

    .trigger[disabled],
    .secondary-button[disabled],
    .danger-button[disabled] {
      opacity: 1;
      cursor: not-allowed;
      transform: none;
      background: #3d4150;
      border-color: #52586a;
      color: #d9deea;
    }

    .details-card {
      padding: 1.25rem;
    }

    .details-card h2 {
      margin: 0 0 1rem;
      font-size: 1.2rem;
    }

    .details-list {
      display: grid;
      gap: 0.9rem;
      margin: 0;
    }

    .details-list div {
      padding-bottom: 0.9rem;
      border-bottom: 1px solid var(--color-border);
    }

    .details-list div:last-child {
      padding-bottom: 0;
      border-bottom: 0;
    }

    .details-list dt {
      margin: 0 0 0.35rem;
      color: var(--color-muted-text);
      font-size: 0.88rem;
    }

    .details-list dd {
      margin: 0;
      font-size: 1rem;
    }

    .status {
      min-height: 1.5rem;
      margin-top: 1rem;
      color: #c8f0d1;
      font-weight: 600;
    }

    .status:focus {
      outline: none;
    }

    dialog {
      width: min(calc(100vw - 2rem), 30rem);
      padding: 0;
      border: 1px solid var(--color-border);
      border-radius: 1.4rem;
      background: linear-gradient(180deg, #171b29, #111521);
      color: var(--color-text);
      box-shadow: var(--shadow-lg);
    }

    dialog::backdrop {
      background: rgba(2, 4, 10, 0.76);
      backdrop-filter: blur(6px);
    }

    .dialog-panel {
      padding: 1.5rem;
    }

    .dialog-panel h2 {
      margin: 0 0 0.75rem;
      font-size: 1.55rem;
    }

    .dialog-panel p {
      margin: 0;
      color: var(--color-muted-text);
      line-height: 1.65;
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 0.8rem;
      margin-top: 1.5rem;
    }

    @media (max-width: 48rem) {
