</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const image = {
      title: "Golden Hour Reflection",
      alt: "A person standing by a lake at sunset, looking across the water toward mountain silhouettes.",
      photographer: "Maya Chen",
      location: "Lake Crescent, Washington",
      size: "5472 x 3648",
      collection: "Landscape Studies",
      added: "Added to library today",
      src: "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80"
    };

    const Header = () => `
      <header class="page-header">
        <div class="header-copy">
          <p class="eyebrow">Image library</p>
          <h1>Preview image</h1>
          <p>Review the selected image, confirm details, and remove it from your library only if you are sure.</p>
        </div>
        <p class="page-badge">Dark gallery view</p>
      </header>
    `;

    const PreviewCard = () => `
      <article class="card preview-card" aria-labelledby="image-title">
        <div class="image-frame">
          <img src="${image.src}" alt="${image.alt}">
        </div>
        <div class="image-meta">
          <span>${image.added}</span>
          <span>Curated in ${image.collection}</span>
        </div>
        <div class="image-title">
          <h2 id="image-title">${image.title}</h2>
          <p>Captured by ${image.photographer}. This image is currently stored in your personal library.</p>
        </div>
        <div class="actions">
          <button type="button" class="secondary-button">Download</button>
          <button type="button" class="trigger" id="delete-trigger">Delete image</button>
        </div>
      </article>
    `;

    const DetailsCard = () => `
      <section class="card details-card" aria-labelledby="details-heading">
        <h2 id="details-heading">Image details</h2>
        <dl class="details-list">
          <div>
            <dt>Photographer</dt>
            <dd>${image.photographer}</dd>
          </div>
          <div>
            <dt>Location</dt>
            <dd>${image.location}</dd>
          </div>
          <div>
            <dt>Resolution</dt>
            <dd>${image.size}</dd>
          </div>
          <div>
            <dt>Collection</dt>
            <dd>${image.collection}</dd>
          </div>
        </dl>
        <p class="status" id="status-message" role="status" aria-atomic="true" tabindex="-1"></p>
      </section>
    `;

    const DeleteDialog = () => `
      <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
        <form method="dialog" class="dialog-panel">
          <h2 id="delete-dialog-title">Delete this image from your library?</h2>
          <p id="delete-dialog-description">This will remove <strong>${image.title}</strong> from your library. You can cancel to keep the image available.</p>
          <div class="dialog-actions">
            <button type="submit" class="secondary-button" value="cancel" autofocus>Cancel</button>
            <button type="submit" class="danger-button" value="delete">Delete image</button>
          </div>
        </form>
      </dialog>
    `;

    const App = () => `
      <div class="page-shell">
        ${Header()}
        <main id="main-content" tabindex="-1">
          <section class="preview-layout" aria-label="Image preview content">
            ${PreviewCard()}
            ${DetailsCard()}
          </section>
        </main>
      </div>
      ${DeleteDialog()}
    `;

    const root = document.getElementById("app");
    root.innerHTML = App();

    const dialog = document.getElementById("delete-dialog");
    const trigger = document.getElementById("delete-trigger");
    const statusMessage = document.getElementById("status-message");

    trigger.addEventListener("click", () => {
      dialog.showModal();
    });

    dialog.addEventListener("close", () => {
      if (dialog.returnValue === "delete") {
        statusMessage.textContent = `"${image.title}" was deleted from your library.`;
        trigger.hidden = true;
        requestAnimationFrame(() => {
          statusMessage.focus();
        });
      }
    });
  </script>
</body>
</html>
